namespace Framework.AI.Core
{
    /// <summary>
    /// エージェントのライフサイクル上の稼働状態。
    /// </summary>
    /// <remarks>
    /// 追跡や巡回などの具体的な行動状態とは区別する。
    /// </remarks>
    public enum AgentState
    {
        /// <summary>
        /// 初期化されていない状態。
        /// </summary>
        Uninitialized = 0,

        /// <summary>
        /// 初期化済みだが稼働していない状態。
        /// </summary>
        Inactive = 1,

        /// <summary>
        /// エージェントが稼働している状態。
        /// </summary>
        Active = 2,

        /// <summary>
        /// 稼働を一時停止している状態。
        /// </summary>
        Paused = 3,

        /// <summary>
        /// エージェントが破棄された状態。
        /// </summary>
        Disposed = 4
    }
}
